const fs = require('node:fs');
const {chromium} = require(process.env.PLAYWRIGHT_MODULE);
const events=[];
const launch=chromium.launch.bind(chromium);
chromium.launch=async(...args)=>{
  const browser=await launch(...args);
  const create=browser.newContext.bind(browser);
  browser.newContext=async(...args)=>{
    const ctx=await create(...args);
    ctx.on('page',p=>{
      const record=(type,data)=>events.push({type,page:p.url(),...data});
      p.on('console',m=>{if(m.type()==='error')record('console',{text:m.text(),location:m.location()});});
      p.on('pageerror',e=>record('pageerror',{text:e.message}));
      p.on('response',r=>{if(r.status()>=400)record('http',{url:r.url(),status:r.status()});});
      p.on('requestfailed',r=>record('requestfailed',{url:r.url(),error:r.failure()?.errorText}));
    });
    return ctx;
  };
  return browser;
};
process.on('exit',()=>fs.writeFileSync(process.env.QA_DIAGNOSTICS,JSON.stringify({events},null,2)+'\n'));
